	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`deprecation expected to be basetypes.ObjectValue, was: %T`, deprecationAttribute))
	}

	guestOsFamilyAttribute, ok := attributes["guest_os_family"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`guest_os_family is missing from object`)

		return NewSpecValueUnknown(), diags
	}

	guestOsFamilyVal, ok := guestOsFamilyAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`guest_os_family expected to be basetypes.StringValue, was: %T`, guestOsFamilyAttribute))
	}

	lifecycleAttribute, ok := attributes["lifecycle"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`lifecycle is missing from object`)

		return NewSpecValueUnknown(), diags
	}

	lifecycleVal, ok := lifecycleAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`lifecycle expected to be basetypes.StringValue, was: %T`, lifecycleAttribute))
	}

	sourceRefAttribute, ok := attributes["source_ref"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`source_ref is missing from object`)

		return NewSpecValueUnknown(), diags
	}

	sourceRefVal, ok := sourceRefAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`source_ref expected to be basetypes.StringValue, was: %T`, sourceRefAttribute))
	}

